mapper.update:
update "h_churn_result"
set churn_rate = #{churnRate},
    top1_reason = #{top1Reason},
    top2_reason = #{top2Reason},
    top3_reason = #{top3Reason}
where model_id = #{modelId}

mapper.select:
select result_id, model_id, churn_rate, top1_reason, top2_reason, top3_reason
from "h_churn_result"
where model_id = #{dataId}

choose.when:
select sm.username                          as username,
       mem.name                             as name,
       max(sm.churn_rate)                   as churnRate
from "h_churn_stat_member" sm
join "h_member" mem on sm.username = mem.username
where sm.gym_id = #{gymId}
  and to_char(sm.stat_date, 'YYYY-MM') = #{period}
  and sm.stat_type = #{statType}
  and sm.stat_key  = #{statKey}
group by sm.username, mem.name
order by churnRate desc

choose.otherwise:
select sm.username    as username,
       mem.name       as name,
       sm.churn_rate  as churnRate
from "h_churn_stat_member" sm
join "h_member" mem on sm.username = mem.username
where sm.gym_id = #{gymId}
  and sm.stat_date = cast(#{period} as date)
  and sm.stat_type = #{statType}
  and sm.stat_key  = #{statKey}
order by sm.churn_rate desc

mapper.select:
select slot, count(*) as cnt from ( select case when extract(hour from ci.check_in) < 6 then '새벽(00-06)' when extract(hour from ci.check_in) < 11 then '오전(06-11)' when extract(hour from ci.check_in) < 14 then '점심(11-14)' when extract(hour from ci.check_in) < 18 then '오후(14-18)' when extract(hour from ci.check_in) < 22 then '저녁(18-22)' else '야간(22-24)' end as slot from "h_check_inout" ci where ci.gym_id = #{gymId} and ci.username in ( select distinct sm.username from "h_churn_stat_member" sm where sm.gym_id = #{gymId} and sm.stat_type = 'complaint' and sm.stat_key = #{statKey}
and to_char(sm.stat_date, 'YYYY-MM') = #{period}
and sm.stat_date = cast(#{period} as date)
) ) t group by slot order by cnt desc
